import 'package:jni/jni.dart';

void main() async {
  final jni = await Jni.spawn(); // start JVM on desktop
  final stringClass = JClass.forName('java.lang.String');
  final ctor = stringClass.getConstructor('([B)');
  final hello = ctor.newInstance([
    JArray.fromList([104, 101, 108, 108, 111].map((c) => JByte(c)))
  ]);
  print(hello.callMethod('toString', []));
}
